const resultsMap = new Map(); 

// ---------- helpers ----------
function extract(entry, regex) {
  const match = entry.match(regex);
  return match ? match[1].trim() : "";
}

function cleanDescription(raw) {
  if (!raw) return "";

  return raw
    .replace(/&lt;img[\s\S]*?&gt;/gi, "")
    .replace(/<img[\s\S]*?>/gi, "")
    .replace(/&lt;a[\s\S]*?\[link\]/gi, "")
    .replace(/<a[\s\S]*?\[link\]/gi, "")
    .replace(/&lt;[\s\S]*?&gt;/g, "")
    .replace(/<[\s\S]*?>/g, "")
    .replace(/&amp;/g, "&")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, " ")
    .trim();
}

function extractSubredditFromLink(link) {
  if (!link || !link.includes("/r/")) return "";
  return link.split("/r/")[1]?.split("/")[0]?.toLowerCase() || "";
}

// ---------- main ----------
for (const item of $input.all()) {
  const xml = item.json.data;
  if (!xml) continue;

  const entries = xml.match(/<entry>([\s\S]*?)<\/entry>/g) || [];

  for (const entry of entries) {
    const title = cleanDescription(
      extract(entry, /<title[^>]*>([\s\S]*?)<\/title>/)
    );

    const link = extract(entry, /<link[^>]*href="([^"]+)"/);
    const updated = extract(entry, /<updated[^>]*>([\s\S]*?)<\/updated>/);

    const description = cleanDescription(
      extract(entry, /<content[^>]*>([\s\S]*?)<\/content>/)
    );

    const subreddit = extractSubredditFromLink(link);
    if (!subreddit) continue;

    const existing = resultsMap.get(subreddit);

    // Decide whether to keep this entry
    if (!existing) {
      resultsMap.set(subreddit, {
        subreddit,
        title,
        description,
        link,
        updated,
        source: "reddit_rss",
        parsedAt: new Date().toISOString()
      });
    } else {

      const betterDescription =
        description.length > (existing.description?.length || 0);

      const newerUpdate =
        updated && (!existing.updated || updated > existing.updated);

      if (betterDescription || newerUpdate) {
        resultsMap.set(subreddit, {
          ...existing,
          title: title || existing.title,
          description: description || existing.description,
          updated: newerUpdate ? updated : existing.updated,
          parsedAt: new Date().toISOString()
        });
      }
    }
  }
}

// ---------- output ----------
return Array.from(resultsMap.values()).map(row => ({
  json: row
}));

